import { cacheTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  body: string
  createdAt: number
}

// Stands in for a database. In a real app this would be your data store.
const posts: Post[] = []

/**
 * Reads the list of posts. The result is cached and tagged with `"posts"`
 * so it can be invalidated when a new post is created.
 */
export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')

  // Return a copy so cached callers can't mutate the underlying store.
  return posts.map((post) => ({ ...post }))
}

/** Persists a new post to the data store. */
export async function savePost(input: {
  title: string
  body: string
}): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title: input.title,
    body: input.body,
    createdAt: Date.now(),
  }
  posts.push(post)
  return post
}

