'use server'

import { updateTag } from 'next/cache'
import { savePost } from './posts'

export async function createPost(formData: FormData) {
  const title = String(formData.get('title') ?? '').trim()
  const body = String(formData.get('body') ?? '').trim()

  if (!title) {
    throw new Error('Title is required')
  }

  await savePost({ title, body })

  // Invalidate the cached posts list. We use `updateTag` rather than
  // `revalidateTag` because it expires the entry with read-your-writes
  // consistency: the cache is refreshed within this request so the next
  // render waits for fresh data instead of being served stale,
  // stale-while-revalidate content.
  updateTag('posts')
}

